<script setup lang="ts">
import {unwrap} from '~/api/client';import{displayError}from'~/utils/errors';definePageMeta({middleware:['auth','admin']});const api=useMarketplaceApi();const shipmentId=ref('');const reason=ref('Verifikasi ulang status ke provider pengiriman');const operationId=ref('');const message=ref('');async function reconcile(){try{const op=unwrap(await api.POST('/admin/shipments/{shipmentId}/reconcile',{params:{path:{shipmentId:shipmentId.value},header:{'Idempotency-Key':crypto.randomUUID()}},body:{reason:reason.value}}));operationId.value=op.id}catch(cause){message.value=displayError(cause).message}}useSeoMeta({title:'Review pengiriman — Niaga'})
</script>
<template><main id="main-content" class="page-shell"><PortalNav area="admin"/><div class="section-heading"><div><p class="eyebrow">Logistics operations</p><h1>Review pengiriman</h1><p>Jalankan verifikasi ke provider untuk shipment berstatus tidak pasti atau perlu review.</p></div></div><p v-if="message" class="surface" role="status">{{message}}</p><form class="surface form-stack narrow-panel" @submit.prevent="reconcile"><label class="form-field">Shipment ID<input v-model="shipmentId" required></label><label class="form-field">Alasan<textarea v-model="reason" minlength="3" required/></label><button>Reconcile shipment</button><OperationStatus v-if="operationId" :operation-id="operationId"/></form></main></template>
